const role=document.querySelector('#role'),scope=document.querySelector('#scope');const summary=()=>document.querySelector('#roleHint').textContent=c.summaries[role.selectedIndex];role.onchange=summary;summary();scope.onchange=()=>document.querySelector('#branches').hidden=scope.value!=='selected_places';document.querySelectorAll('form').forEach(f=>f.onsubmit=e=>{e.preventDefault();f.querySelector('.status').textContent=c.demo});
if(state==='error'){for(const id of ['branchError','categoryError','programError','emailError']){const e=document.getElementById(id);e.hidden=false;e.textContent=c.errorText;e.closest('label').querySelector('input,select').setAttribute('aria-invalid','true')}}
